const express=require('express');
const c=require('./bundlePromotion.controller');
const authenticate=require('../../middleware/authenticate');
const authorize=require('../../middleware/authorize');
const validateRequest=require('../../middleware/validateRequest');
const v=require('./bundlePromotion.validation');
const r=express.Router();r.use(authenticate);
const route=(method,path,permission,validation,handler)=>r[method](path,authorize(permission),validation,validateRequest,handler);
route('get','/','bundle-promotions.read',v.listConfigsValidation,c.listConfigs);
route('post','/','bundle-promotions.create',v.createConfigValidation,c.createConfig);
route('get','/:id','bundle-promotions.read',v.configIdValidation,c.getConfigById);
route('put','/:id','bundle-promotions.update',v.updateConfigValidation,c.updateConfig);
route('patch','/:id/status','bundle-promotions.update',v.changeConfigStatusValidation,c.changeConfigStatus);
route('delete','/:id','bundle-promotions.delete',v.configIdValidation,c.deleteConfig);
route('get','/:configId/bundles','bundle-promotions.read',[require('express-validator').param('configId').isUUID()],c.listBundles);
route('post','/:configId/bundles','bundle-promotions.create',v.createBundleValidation,c.createBundle);
route('get','/bundles/:bundleId','bundle-promotions.read',v.bundleIdValidation,c.getBundleById);
route('put','/bundles/:bundleId','bundle-promotions.update',v.updateBundleValidation,c.updateBundle);
route('patch','/bundles/:bundleId/status','bundle-promotions.update',v.changeBundleStatusValidation,c.changeBundleStatus);
route('delete','/bundles/:bundleId','bundle-promotions.delete',v.bundleIdValidation,c.deleteBundle);
route('get','/bundles/:bundleId/items','bundle-promotions.read',v.bundleIdValidation,c.listItems);
route('post','/bundles/:bundleId/items','bundle-promotions.create',v.createBundleItemValidation,c.createItem);
route('get','/items/:itemId','bundle-promotions.read',v.itemIdValidation,c.getItemById);
route('put','/items/:itemId','bundle-promotions.update',v.updateBundleItemValidation,c.updateItem);
route('patch','/items/:itemId/status','bundle-promotions.update',v.changeBundleItemStatusValidation,c.changeItemStatus);
route('delete','/items/:itemId','bundle-promotions.delete',v.itemIdValidation,c.deleteItem);
module.exports=r;
